import{safeUrl as d}from"./store.min.js";const f=/\bhttps?:\/\/[^\s<>"'()[\]{}]+/i,u=/(?:\$|\bUSD\s?)\s?(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)\s?([kK]\b)?/g,m=/^\s*(?:-|\u2013|\u2014|to|and)\s*(?:\$|USD\s?)?\s?(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)\s?([kK]\b)?/i,x=/^[\s.,]*(?:\/\s?(?:hr|hour|h)\b|per\s+hour|an\s+hour|hourly)/i;function l(t,r){const n=Number(String(t).replace(/,/g,""));return Number.isFinite(n)?Math.round(r?n*1e3:n):null}export function findUrl(t){const r=f.exec(String(t||""));return r?d(r[0].replace(/[.,;:!?]+$/,"")):""}export function findSalary(t){const r=String(t||"");u.lastIndex=0;let n;for(;(n=u.exec(r))!==null;){const i=r.slice(n.index+n[0].length),s=m.exec(i);if(!s)continue;const c=!!s[2];let e=l(n[1],n[2]);const o=l(s[1],c);if(!e||!o)continue;!n[2]&&c&&e<1e3&&(e*=1e3);const a=i.slice(s[0].length,s[0].length+24),h=x.test(a)||Math.max(e,o)<1e3?"hour":"year";return{min:Math.min(e,o),max:Math.max(e,o),period:h}}return null}export function readPosting(t){return{url:findUrl(t),salary:findSalary(t)}}
